contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "not enough balance");

        uint256 contractBefore = address(c).balance;

        c.addToBalance{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceBeforeWithdraw = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractBeforeWithdraw = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 balanceAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 contractAfterWithdraw = address(c).balance;

        assert(
            reverted
                ? (balanceAfter == balanceBeforeWithdraw && contractAfterWithdraw == contractBeforeWithdraw)
                : (balanceAfter == 0 && contractBeforeWithdraw == contractAfterWithdraw + balanceBeforeWithdraw)
        );
    }

    receive() external payable {}
}

