pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        uint256 contractBefore = address(c).balance;
        try c.addToBalance{value: depositAmount}() {} catch { return; }
        uint256 balanceBeforeWithdraw;
        try c.getBalance(address(this)) returns (uint256 __r) { balanceBeforeWithdraw = __r; } catch { return; }
        uint256 contractBeforeWithdraw = address(c).balance;
        bool reverted;
        try c.withdrawBalance() { reverted = false; } catch { reverted = true; }
        uint256 balanceAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balanceAfter = __r; } catch { return; }
        uint256 contractAfterWithdraw = address(c).balance;
        assertTrue(reverted
                ? (balanceAfter == balanceBeforeWithdraw && contractAfterWithdraw == contractBeforeWithdraw)
                : (balanceAfter == 0 && contractBeforeWithdraw == contractAfterWithdraw + balanceBeforeWithdraw));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
